import{_ as o,c as a,o as s,ai as r}from"./chunks/framework.DMRKKuRm.js";const m=JSON.parse('{"title":"Postulaciones","description":"","frontmatter":{},"headers":[],"relativePath":"Servidor/postulaciones.md","filePath":"Servidor/postulaciones.md"}'),i={name:"Servidor/postulaciones.md"};function t(n,e,l,c,d,u){return s(),a("div",null,e[0]||(e[0]=[r('<h1 id="postulaciones" tabindex="-1">Postulaciones <a class="header-anchor" href="#postulaciones" aria-label="Permalink to &quot;Postulaciones&quot;">​</a></h1><p>¿Quieres formar parte del Staff de SilkCraft?</p><h2 id="¡unete-al-equipo-silkcraft" tabindex="-1">¡ÚNETE AL EQUIPO SILKCRAFT! <a class="header-anchor" href="#¡unete-al-equipo-silkcraft" aria-label="Permalink to &quot;¡ÚNETE AL EQUIPO SILKCRAFT!&quot;">​</a></h2><p>Estamos emocionados de anunciar que abrimos postulaciones para nuevos miembros del staff. Si te apasiona Minecraft y quieres ayudar a crear una comunidad increíble, <strong>¡esta es tu oportunidad!</strong></p><h2 id="requisitos-minimos" tabindex="-1">Requisitos mínimos <a class="header-anchor" href="#requisitos-minimos" aria-label="Permalink to &quot;Requisitos mínimos&quot;">​</a></h2><p>Para postularte como staff, debes cumplir con <strong>todos</strong> los siguientes requisitos:</p><ul><li><strong>Tener más de 16 años</strong></li><li><strong>Tener la capacidad de grabar</strong></li><li><strong>Ser un jugador activo</strong>, comprometido con el servidor y con un buen historial dentro del mismo</li><li><strong>Tener una participación positiva en la comunidad</strong> y llevarse bien con otros jugadores</li><li><strong>No haber recibido ninguna sanción grave</strong> (como baneo) por violar las reglas del servidor, como: <ul><li>Dupeos</li><li>Romper la economía</li><li>Uso de hacks</li><li>Cualquier otra actividad que afecte negativamente la experiencia de juego de los demás jugadores</li></ul></li><li><strong>Poseer un micrófono funcional</strong> para facilitar la comunicación dentro del equipo de staff</li><li><strong>Saber de la SS y tener experiencia en ello</strong> (Screenshare)</li><li><strong>Tener rango en el servidor</strong> (No es obligatorio ni necesario, pero es valorado)</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Cumplir con todos los requisitos mínimos es esencial. Asegúrate de revisarlos antes de postularte.</p></div><h2 id="enlace-para-postularse" tabindex="-1">Enlace para postularse <a class="header-anchor" href="#enlace-para-postularse" aria-label="Permalink to &quot;Enlace para postularse&quot;">​</a></h2><p>Completa el formulario de postulación haciendo clic en el siguiente enlace:</p><div style="text-align:center;margin:2rem 0;"><a href="https://docs.google.com/forms/d/e/1FAIpQLSc6-U3AwGXveG05bTEiJFEfNB2fXL-iyaWRvzXQ1Y2ZE39BcQ/viewform" target="_blank" style="display:inline-block;padding:1rem 2rem;background:linear-gradient(135deg, #FFB7C5 0%, #D87093 100%);color:white;text-decoration:none;border-radius:8px;font-weight:bold;font-size:1.1rem;transition:transform 0.2s;"> HAZ CLICK AQUÍ PARA POSTULARTE </a></div><h2 id="informacion-importante" tabindex="-1">Información importante <a class="header-anchor" href="#informacion-importante" aria-label="Permalink to &quot;Información importante&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">ADVERTENCIA</p><p><strong>No menciones a STAFF</strong> para que revise las postulaciones, ya que puede ser molesto y te podrían sancionar. Una vez sancionado, <strong>no te podrás postular</strong>.</p></div><div class="tip custom-block"><p class="custom-block-title">Consejo</p><p>Recuerda tener los <strong>MDs (mensajes directos) abiertos en Discord</strong>, por si te contactan para ser Staff.</p></div><h2 id="proceso-de-seleccion" tabindex="-1">Proceso de selección <a class="header-anchor" href="#proceso-de-seleccion" aria-label="Permalink to &quot;Proceso de selección&quot;">​</a></h2><p>Una vez que hayas enviado tu postulación:</p><ol><li><strong>Nuestro equipo de reclutamiento la revisará cuidadosamente</strong></li><li>Si cumples con los requisitos, <strong>serás contactado</strong> a través de Discord</li><li>Mantén tus <strong>MDs abiertos</strong> para recibir la comunicación</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>El proceso de revisión puede tomar tiempo. Sé paciente y no contactes al staff directamente sobre tu postulación.</p></div><p>¿Tienes más preguntas? Únete a nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a> y pregunta en el canal correspondiente.</p>',19)]))}const g=o(i,[["render",t]]);export{m as __pageData,g as default};
